cd /repo/evals/terraform-secure-iac/results/raw/2026-10-26/tsi-01-remote-state/with-skill/run-1/workspace
mkdir bootstrap
cp versions.tf bootstrap/versions.tf
cat > bootstrap/variables.tf <<'EOF'
variable "region" {
  type        = string
  description = "AWS region the state bucket and its KMS key are created in."
  default     = "eu-north-1"
}

variable "state_bucket_name" {
  type        = string
  description = "Name of the S3 bucket that holds Terraform state. Must be globally unique and must match the bucket in the backend block of the root configuration."
  default     = "reports-terraform-state"
}
EOF
cat > bootstrap/providers.tf <<'EOF'
provider "aws" {
  region = var.region
}
EOF
cat > bootstrap/main.tf <<'EOF'
resource "aws_kms_key" "state" {
  description         = "Encrypts Terraform state in ${var.state_bucket_name}"
  enable_key_rotation = true
}

resource "aws_kms_alias" "state" {
  name          = "alias/${var.state_bucket_name}"
  target_key_id = aws_kms_key.state.key_id
}

resource "aws_s3_bucket" "state" {
  bucket = var.state_bucket_name

  # Losing this bucket loses the record of every managed resource.
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  # Versioning must exist first so noncurrent versions are tracked.
  depends_on = [aws_s3_bucket_versioning.state]

  rule {
    id     = "expire-old-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

data "aws_iam_policy_document" "state_bucket" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > bootstrap/outputs.tf <<'EOF'
output "state_bucket_name" {
  description = "Name of the state bucket, for the bucket argument of the root backend block."
  value       = aws_s3_bucket.state.id
}

output "state_kms_key_arn" {
  description = "ARN of the KMS key that encrypts state. Principals that run plan or apply need kms:Decrypt, kms:Encrypt and kms:GenerateDataKey on it."
  value       = aws_kms_key.state.arn
}
EOF
cat > backend.tf <<'EOF'
# The bucket is created by bootstrap/. Backend blocks cannot use variables, so the name is literal
# and must match bootstrap's state_bucket_name. Only non-secret metadata belongs here; credentials
# come from the default AWS credential chain.
terraform {
  backend "s3" {
    bucket       = "reports-terraform-state"
    key          = "reports/staging/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }
}
EOF
cat > .gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
*.tfplan
tfplan
crash.log
crash.*.log
*.tfvars
*.auto.tfvars
.terraformrc
terraform.rc
EOF
terraform fmt -recursive -check -diff; (cd bootstrap && terraform init -backend=false -input=false >/dev/null && terraform validate); terraform init -backend=false -input=false >/dev/null && terraform validate; checkov -d bootstrap --quiet --compact 2>&1 | tail -40; git status --short

